rollback.sql:
DO $$
DECLARE
    R          RECORD;
    V_SQLSTATE TEXT;
    V_SQLMSG   TEXT;
    V_SQLERRMC TEXT;
BEGIN
    FOR R IN
        SELECT PRODUCT_ID, INTERNAL_CUSIP, DISPLAY_NM, ASSET_TYPE_ID,
               CASE WHEN INTERNAL_CUSIP LIKE '%usdt.crypto' THEN 'USD' ELSE CCY END AS CCY,
               REPLACE(DESCRIPTION, 'BTC/USDT', 'BTC-USD') AS DESCRIPTION
          FROM INST.PRODUCT
         WHERE IS_CURRENT_IND = 'Y'
           AND INTERNAL_CUSIP LIKE '%.crypto'
           AND EXCHANGE IS NULL
    LOOP
        CALL INST.SP_INS_PRODUCT(
            R.PRODUCT_ID, R.INTERNAL_CUSIP, R.DISPLAY_NM, R.ASSET_TYPE_ID,
            'crypto', R.CCY, R.DESCRIPTION, 'system',
            V_SQLSTATE, V_SQLMSG, V_SQLERRMC
        );
    END LOOP;
END $$;
